/// # `GET /_matrix/client/r0/rooms/{roomId}/messages`
///
/// Allows paginating through room history.
///
/// - Only works if the user is joined (TODO: always allow, but only show events
///   where the user was joined, depending on `history_visibility`)
pub(crate) async fn get_message_events_route(
	State(services): State<crate::State>,
	body: Ruma<get_message_events::v3::Request>,
) -> Result<get_message_events::v3::Response> {
	get_messages(&services, MessagesArgs {
		room_id: &body.room_id,
		sender_user: body.sender_user(),
		sender_device: body.sender_device.as_deref(),
		from: body.from.as_deref(),
		to: body.to.as_deref(),
		dir: body.dir,
		limit: Some(body.limit),
		filter: &body.filter,
		bypass_visibility: false,
	})
	.await
}

pub(crate) async fn get_room_event_route(
	State(services): State<crate::State>,
	body: Ruma<get_room_event::v3::Request>,
) -> Result<get_room_event::v3::Response> {
	let sender_user = body.sender_user();
	let event_id = &body.event_id;
	let room_id = &body.room_id;

	let event = services
		.timeline
		.get_pdu(event_id)
		.map_err(|_| err!(Request(NotFound("Event {} not found.", event_id))));

	let retained_event = body
		.include_unredacted_content
		.then_async(async || {
			let is_admin = services.admin.user_is_admin(sender_user);

			let can_redact = services
				.config
				.allow_room_admins_to_request_unredacted_events
				.then_async(|| {
					services
						.state_accessor
						.get_power_levels(room_id)
						.map_ok_or(false, |power_levels| {
							power_levels.for_user(sender_user) >= power_levels.redact
						})
				})
				.unwrap_or(false);

			pin_mut!(is_admin, can_redact);

			if is_admin.or(can_redact).await {
				services
					.retention
					.get_original_pdu(event_id)
					.await
					.map_err(|_| err!(Request(NotFound("Event {} not found.", event_id))))
			} else {
				Err!(Request(Forbidden("You are not allowed to see the original event")))
			}
		});

	let visible = services
		.state_accessor
		.user_can_see_event(sender_user, room_id, event_id);

	let (mut event, retained_event, visible): (Result<Pdu>, Option<Result<Pdu>>, _) =
		join3(event, retained_event, visible).await;

	if event.as_ref().is_err_or(Event::is_redacted)
		&& let Some(retained_event) = retained_event
	{
		event = retained_event;
	}

	let mut event = event?;

	if !visible {
		return Err!(Request(NotFound("Event not found.")));
	}

	if is_ignored_pdu(&services, &event, body.sender_user()).await {
		return Err!(HttpJson(NOT_FOUND, {
			"errcode": "M_SENDER_IGNORED",
			"error": "You have ignored the user that sent this event",
			"sender": event.sender().as_str(),
		}));
	}

	debug_assert!(
		event.event_id() == event_id && event.room_id() == room_id,
		"Fetched PDU must match requested"
	);

	event.add_age().ok();

	let encrypted = services
		.state_accessor
		.is_encrypted_room(room_id)
		.await;

	annotate_membership(&services, &mut event, sender_user, encrypted).await;

	let event = services
		.pdu_metadata
		.bundle_aggregations(sender_user, event)
		.await;

	Ok(get_room_event::v3::Response { event: event.into_format() })
}

pub(crate) async fn get_member_events_route(
	State(services): State<crate::State>,
	body: Ruma<get_member_events::v3::Request>,
) -> Result<get_member_events::v3::Response> {
	if !services
		.state_accessor
		.user_can_see_state_events(body.sender_user(), &body.room_id)
		.await
	{
		return Err!(Request(Forbidden(
			"You aren't a member of the room and weren't previously a member of the room."
		)));
	}

	let at: Option<PduCount> = body
		.at
		.as_deref()
		.map(str::parse)
		.transpose()
		.map_err(|_| err!(Request(InvalidParam("Invalid `at` token."))))?;

	let shortstatehash = match at {
		| None => services
			.state
			.get_room_shortstatehash(&body.room_id)
			.await
			.map_err(|e| err!(Database("Missing state for {:?}: {e:?}", body.room_id)))?,

		| Some(at) =>
			services
				.timeline
				.shortstatehash_after(&body.room_id, at)
				.await?,
	};

	let membership = body.membership.as_ref();
	let not_membership = body.not_membership.as_ref();
	let membership_filter = |content: &RoomMemberEventContent| {
		membership.is_none_or(is_equal_to!(&content.membership))
			&& not_membership.is_none_or(is_not_equal_to!(&content.membership))
	};

	Ok(get_member_events::v3::Response {
		chunk: services
			.state_accessor
			.state_full(shortstatehash)
			.ready_filter(|((ty, _), _)| *ty == StateEventType::RoomMember)
			.map(at!(1))
			.ready_filter(|pdu| {
				pdu.get_content::<RoomMemberEventContent>()
					.as_ref()
					.is_ok_and(membership_filter)
			})
			.map(Event::into_format)
			.collect()
			.boxed()
			.await,
	})
}

async fn paginate_relations_with_filter(
	services: &Services,
	sender_user: &UserId,
	room_id: &RoomId,
	target: &EventId,
	filter_event_type: Option<TimelineEventType>,
	filter_rel_type: Option<RelationType>,
	from: Option<&str>,
	to: Option<&str>,
	limit: Option<UInt>,
	recurse: bool,
	dir: Direction,
) -> Result<get_relating_events::v1::Response> {
	let from: Option<PduCount> = from.map(str::parse).transpose()?;

	let to: Option<PduCount> = to.map(str::parse).flat_ok();

	// Spec (v1.10) recommends depth of at least 3
	let max_depth: usize = if recurse { 3 } else { 0 };

	let limit = limit.map_or(30, |limit| usize_from_ruma_bounded(limit, 30, 100));

	let target_event_id: &EventId = target;

	let target = services
		.timeline
		.get_pdu_id(target)
		.map_ok(PduId::from)
		.map_ok(Ok::<_, Error>);

	let visible = services
		.state_accessor
		.user_can_see_state_events(sender_user, room_id)
		.map(|visible| {
			visible
				.into_option()
				.ok_or_else(|| err!(Request(Forbidden("You cannot view this room."))))
		});

	let shortroomid = services.short.get_shortroomid(room_id);

	let (shortroomid, target, ()) = try_join3(shortroomid, target, visible).await?;

	let Ok(target) = target else {
		return Ok(get_relating_events::v1::Response::new(Vec::new()));
	};

	if shortroomid != target.shortroomid {
		return Err!(Request(NotFound("Event not found in room.")));
	}

	if let PduCount::Backfilled(_) = target.count {
		return Ok(get_relating_events::v1::Response::new(Vec::new()));
	}

	if let Ok(target_pdu) = services.timeline.get_pdu(target_event_id).await
		&& is_ignored_pdu(services, &target_pdu, sender_user).await
	{
		return Err!(HttpJson(NOT_FOUND, {
			"errcode": "M_SENDER_IGNORED",
			"error": "You have ignored the user that sent this event",
			"sender": target_pdu.sender().as_str(),
		}));
	}

	let fetch = |depth: usize, count: PduCount| {
		services
			.pdu_metadata
			.get_relations(shortroomid, count, from, dir, Some(sender_user))
			.map(move |(count, pdu)| (depth, count, pdu))
			.ready_filter(|(_, count, _)| matches!(count, PduCount::Normal(_)))
			.boxed()
	};

	let events = unfold(select_all(once(fetch(0, target.count))), async |mut relations| {
		let (depth, count, pdu) = relations.next().await?;

		if depth < max_depth {
			relations.push(fetch(depth.saturating_add(1), count));
		}

		Some(((depth, count, pdu), relations))
	})
	.ready_take_while(|&(_, count, _)| Some(count) != to)
	.ready_filter(|(_, _, pdu)| {
		filter_event_type
			.as_ref()
			.is_none_or(|kind| kind == pdu.kind())
	})
	.ready_filter(|(_, _, pdu)| {
		filter_rel_type
			.as_ref()
			.is_none_or(|rel_type| rel_type.relation_type_equal(pdu))
	})
	.wide_filter_map(async |(depth, count, pdu)| {
		services
			.state_accessor
			.user_can_see_event(sender_user, pdu.room_id(), pdu.event_id())
			.await
			.then_some((depth, count, pdu))
	})
	.take(limit)
	.wide_then(async |(depth, count, pdu)| {
		let pdu = services
			.pdu_metadata
			.bundle_aggregations(sender_user, pdu)
			.await;

		(depth, count, pdu)
	})
	.collect::<Vec<_>>()
	.await;

	Ok(get_relating_events::v1::Response {
		recursion_depth: max_depth
			.gt(&0)
			.then(|| events.iter().map(at!(0)))
			.into_iter()
			.flatten()
			.max()
			.map(TryInto::try_into)
			.transpose()?,

		next_batch: events
			.last()
			.map(at!(1))
			.as_ref()
			.map(ToString::to_string),

		prev_batch: events
			.first()
			.map(at!(1))
			.or(from)
			.as_ref()
			.map(ToString::to_string),

		chunk: events
			.into_iter()
			.map(at!(2))
			.map(Event::into_format)
			.collect(),
	})
}

